            lib.skill._lb_buff={
                trigger:{global:'gameStart',player:'enterGame'},
                forced:true,
                charlotte:true,
                popup:false,
                ruleSkill:true,
                filter:function(event,player){
                return player.name1=="sanying_lvbu"||player.name2=="sanying_lvbu";
                },
                content:function (){
                'step 0'
                var list=get.gainableCharacters();
                var list2 = [];
                var players = game.players;
                for (var i = 0; i < players.length; i++) {
                    list2.add(players[i].name);
                    list2.add(players[i].name1);
                    list2.add(players[i].name2);
                }
                var players=game.players.concat(game.dead);
                for(var i=0;i<players.length;i++){
                    list.remove(players[i].name);
                    list.remove(players[i].name1);
                    list.remove(players[i].name2);
                }
                list.remove(list2);
                if(list){
                    var dialog=ui.create.dialog('选择一张武将牌','hidden');
                    dialog.add([list.randomGets(10),'character']);
                    player.chooseButton(dialog).ai=function(button){return get.buttonValue(button.link,true)};  
                }   
                else event.finish();
                'step 1'
                if(result.bool&&result.links&&result.links.length){
                player.flashAvatar('_lb_buff', result.links[0]);
                player.unmark(player.storage.qita_lvbu_buff+'_charactermark');
                var name=result.links[0];
                var list=[];
                var skills=lib.character[result.links[0]][3];
                for(var j=0;j<skills.length;j++){
                if(lib.translate[skills[j]+'_info']&&lib.skill[skills[j]]&&!player.hasSkill(skills[j]&&!lib.skill[skills[j]].zhuSkill)){
                    list.push(skills[j]);
                }
                }
                player.addAdditionalSkill('qita_lvbu_buff',list);
                player.markCharacter(name,null,true,true);
                game.addVideo('markCharacter',player,{
                name:'lvbu_buff',
                content:'',
                id:'qita_lvbu_buff',
                target:name
                });
                player.storage.qita_lvbu_buff=name;
                player.update();        
                }
                else event.goto(0);
                },
            };
            lib.skill._ns_bianshen={
                marktext:"变",
                mark:true,
                ruleSkill:true,
                locked:true,
                intro:{
                    name:"变身",
                    content:function(storage,player){
                    var map={
                        jingjue:'警觉',
                        ruizhi:'睿智',
                        baonu:'暴怒'
                    };
                    if(player.storage.ns_bianshen2&&player.storage.ns_bianshen3) return '下一个状态：'+map[player.storage.ns_bianshen_next];
                    return '下一个状态：未知'; 
                    },
                },
                trigger:{
                   player:"phaseBefore",
                },
                forced:true,
                charlotte:true,
                popup:false,
                ruleSkill:true,
                filter:function(event,player){
                return (player.name1=='ol_old_nianshou'||player.name2=='ol_old_nianshou')||(player.name1=='ol_old_nianshou1'||player.name2=='ol_old_nianshou1')||(player.name1=='ol_old_nianshou2'||player.name2=='ol_old_nianshou2')||(player.name1=='ol_old_nianshou3'||player.name2=='ol_old_nianshou3');
                },
                content:function(){
                "step 0"
                if(!player.storage.ns_bianshen) player.storage.ns_bianshen=['jingjue','ruizhi','baonu'];
                if(!player.storage.ns_bianshen_next) player.storage.ns_bianshen_next=player.storage.ns_bianshen.randomGet();
                player.markSkill('ns_bianshen');
                "step 1"
                if(player.storage.ns_bianshen_previous) player.removeSkill('ns_'+player.storage.ns_bianshen_previous);
                player.addSkill('ns_'+player.storage.ns_bianshen_next);
                player.storage.ns_bianshen_previous=player.storage.ns_bianshen_next;
                player.storage.ns_bianshen.remove(player.storage.ns_bianshen_next);
                if(!player.storage.ns_bianshen1) player.storage.ns_bianshen1=player.storage.ns_bianshen_next;
                switch(player.storage.ns_bianshen_next){
					case 'jingjue':
					player.addAdditionalSkill('ns_jingjue',["nianshou_jingti","nianshou_jingkong"]);
					break;
					case 'ruizhi':
					player.addAdditionalSkill('ns_ruizhi',['nianshou_ruya','nianshou_boxue']);
					break;
					case 'baonu':
					player.addAdditionalSkill('ns_baonu',['nianshou_kuangbao','nianshou_shouyi']);
					break;
				}
                player.update();
                "step 2"
                if(!player.storage.ns_bianshen.length){
                    player.storage.ns_bianshen=['jingjue','ruizhi','baonu'];
                    player.storage.ns_bianshen_next=player.storage.ns_bianshen1;
                }
                else{
                    if(!player.storage.ns_bianshen2) player.storage.ns_bianshen_next=player.storage.ns_bianshen.randomGet();
                    else player.storage.ns_bianshen_next=player.storage.ns_bianshen.includes(player.storage.ns_bianshen2)?player.storage.ns_bianshen2:player.storage.ns_bianshen3?player.storage.ns_bianshen3:player.storage.ns_bianshen.randomGet();
                } 
                player.update();
                "step 3"
                if(!player.storage.ns_bianshen2) player.storage.ns_bianshen2=player.storage.ns_bianshen_next;
                else if(!player.storage.ns_bianshen3) player.storage.ns_bianshen3=player.storage.ns_bianshen_next;
                player.update();
                },
                derivation:["nianshou_ruya","nianshou_boxue","nianshou_jingti","nianshou_jingkong","nianshou_kuangbao","nianshou_shouyi"],
            };
            lib.skill._ns_old_bianshen={
                marktext:"变",
                mark:true,
                ruleSkill:true,
                locked:true,
                intro:{
                    name:"变身",
                    content:function(storage,player){
                    var map={
                        jingjue:'警觉',
                        ruizhi:'睿智',
                        baonu:'暴怒',
                        renxing:'任性'
                    };
                    if(player.storage.ns_old_bianshen_next) return '下一个状态：'+map[player.storage.ns_old_bianshen_next];
                    return '下一个状态：未知'; 
                    },
                },
                trigger:{
                   global:"roundStart",
                },
                forced:true,
                charlotte:true,
                popup:false,
                ruleSkill:true,
                filter:function(event,player){
                return ((player.name1=='old_nianshou'||player.name2=='old_nianshou')||(player.name1=='old_nianshou_jingjue'||player.name2=='old_nianshou_jingjue')||(player.name1=='old_nianshou_renxing'||player.name2=='old_nianshou_renxing')||(player.name1=='old_nianshou_ruizhi'||player.name2=='old_nianshou_ruizhi')||(player.name1=='old_nianshou_baonu'||player.name2=='old_nianshou_baonu'))&&game.roundNumber>=2;
                },
                content:function(){
                "step 0"
                if(!player.storage.ns_old_bianshen) player.storage.ns_old_bianshen=['jingjue','ruizhi','baonu','renxing'];
                if(!player.storage.ns_old_bianshen_next) player.storage.ns_old_bianshen_next=player.storage.ns_old_bianshen.randomGet();
                player.markSkill('ns_old_bianshen');
                "step 1"
                if(player.storage.ns_old_bianshen_previous) player.removeSkill('ns_old_'+player.storage.ns_old_bianshen_previous);
                player.addSkill('ns_old_'+player.storage.ns_old_bianshen_next);
                player.storage.ns_old_bianshen_previous=player.storage.ns_old_bianshen_next;
                player.storage.ns_old_bianshen.remove(player.storage.ns_old_bianshen_next);
                switch(player.storage.ns_old_bianshen_next){
					case 'jingjue':
					if(player.name2&&get.character(player.name2)[3].includes('ns_old_bianshen')) player.reinitCharacter(player.name2, 'old_nianshou_jingjue');
			    	else player.reinitCharacter(player.name1, 'old_nianshou_jingjue');
					break;
					case 'renxing':
					if(player.name2&&get.character(player.name2)[3].includes('ns_old_bianshen')) player.reinitCharacter(player.name2, 'old_nianshou_renxing');
			    	else player.reinitCharacter(player.name1, 'old_nianshou_renxing');
					break;
					case 'ruizhi':
					if(player.name2&&get.character(player.name2)[3].includes('ns_old_bianshen')) player.reinitCharacter(player.name2, 'old_nianshou_ruizhi');
			    	else player.reinitCharacter(player.name1, 'old_nianshou_ruizhi');
					break;
					case 'baonu':
					if(player.name2&&get.character(player.name2)[3].includes('ns_old_bianshen')) player.reinitCharacter(player.name2, 'old_nianshou_baonu');
			    	else player.reinitCharacter(player.name1, 'old_nianshou_baonu');
					break;
				}
                player.update();
                "step 2"
                if(!player.storage.ns_old_bianshen.length) player.storage.ns_old_bianshen=['jingjue','ruizhi','baonu','renxing'];
                player.storage.ns_old_bianshen_next=player.storage.ns_old_bianshen.randomGet();
                player.update();
                },
                derivation:["nianshou_ruizhi","wenhe_weimua","nianshou_jingjue","nianshou_renxing","nianshou_baonu","shanhe_shouyi"],
            };
