            "qunying_qianhuana":{
                group:["qunying_qianhuana_add","qunying_qianhuana_use"],
                intro:{
                    content:"expansion",
                    markcount:"expansion",
                },
                onremove:function(player,skill){
                    var cards=player.getExpansions(skill);
                    if(cards.length) player.loseToDiscardpile(cards);
                },
                ai:{
                    threaten:1.8,
                },
                audio:"ext:活动BOSS/audio/skill:2",
                subSkill:{
                    add:{
                        trigger:{
                            global:"damageEnd",
                        },
                        filter:function(event,player){
                        var suits=[],cards=player.getExpansions('qunying_qianhuana');
                        for(var i=0;i<cards.length;i++){
                            suits.add(get.suit(cards[i]));
                        }
                        if(suits.length>=lib.suit.length) return false;
                        return (event.player==player||player.getFriends().includes(event.player))&&player.hasCard(function(card){
                            if(get.position(card)=='h') return true;
                            return !suits.includes(get.suit(card));
                        },'he');
                        },
                        direct:true,
                        audio:"qunying_qianhuana",
                        content:function(){
                        'step 0'
                        var suits=[],cards=player.getExpansions('qunying_qianhuana');
                        for(var i=0;i<cards.length;i++){
                            suits.add(get.suit(cards[i]));
                        }
                        player.chooseCard('he',get.prompt2('qunying_qianhuana'),function(card){return !_status.event.suits.includes(get.suit(card))}).set('ai',function(card){return 9-get.value(card)}).set('suits',suits).setHiddenSkill('qunying_qianhuana');
                        'step 1'
                        if(result.bool){
                            player.logSkill('qunying_qianhuana');
                            var card=result.cards[0];
                            player.addToExpansion(card,player,'give').gaintag.add('qunying_qianhuana');
                        }
                        },
                        sub:true,
                    },
                    use:{
                        trigger:{
                            global:"useCardToTarget",
                        },
                        filter:function(event,player){
                        if(!['basic','trick'].includes(get.type(event.card,'trick'))) return false;
                        return event.target&&(player.getFriends().includes(event.target)||event.target==player)&&event.targets.length==1&&player.getExpansions('qunying_qianhuana').length&&!event.getParent().excluded.includes(event.target);
                        },
                        direct:true,
                        audio:"qunying_qianhuana",
                        content:function(){
                        'step 0'
                        var goon=get.effect(trigger.target,trigger.card,trigger.player,player)<0;
						if(goon){
							if(['tiesuo','diaohulishan','lianjunshengyan','zhibi','chiling','lulitongxin'].includes(trigger.card.name)) goon=false;
							else if(trigger.card.name=='sha'){
								if (!lib.filter.cardRespondable(trigger.card, trigger.target, trigger)) goon = true; 
								else {
								    if (trigger.target.mayHaveShan(player, 'use', trigger.target.getCards(i => {return i.hasGaintag('sha_notshan')})) && trigger.target.hp >= 3) goon = false;
								}
							}
							else if(trigger.card.name=='guohe'){
								if(trigger.target.countCards('he')>=3||!trigger.target.countCards('h')) goon=false;
							}
							else if(trigger.card.name=='shuiyanqijunx'){
								if(trigger.target.countCards('e')<=1) goon=false;
							}
						}
						player.chooseButton().set('goon',goon).set('ai',function(button){
							if(_status.event.goon) return 1;
							return 0;
						}).set('createDialog',[get.prompt('qunying_qianhuana'),'<div class="text center">移去一张“千幻”牌令'+get.translation(trigger.player)+'对'+get.translation(trigger.target)+'的'+get.translation(trigger.card)+'失效</div>',player.getExpansions('qunying_qianhuana')]);
                        'step 1'
                        if(result.bool){
                            player.logSkill('qunying_qianhuana');
                            trigger.getParent().targets.remove(trigger.target);
                            var card=result.links[0];
                            player.loseToDiscardpile(card);
                        }
                        },
                        sub:true,
                    },
                },
            },
