            shanhe_huisheng:{
				trigger:{player:'damageBegin4'},
				direct:true,
				filter:function(event,player){
					if(!player.countCards('he')) return false;
					if(!event.source||event.source==player||!event.source.isIn()) return false;
					if(player.storage.shanhe_huisheng&&player.storage.shanhe_huisheng.includes(event.source)) return false;
					return true;
				},
				init:function(player){
					if(player.storage.shanhe_huisheng) player.storage.shanhe_huisheng=[];
				},
				content:function(){
				'step 0'
				var att=(get.attitude(player,trigger.source)>0);
				var goon=false;
				if(player.hp==1){
					goon=true;
				}
				else{
					var he=player.getCards('he');
					var num=0;
					for(var i=0;i<he.length;i++){
						if(get.value(he[i])<8){
							num++;
							if(num>=2){
								goon=true;break;
							}
						}
					}
				}
				player.chooseCard('he',[1,player.countCards('he')],get.prompt2('shanhe_huisheng',trigger.source)).set('ai',function(card){
					if(_status.event.att){
						return 10-get.value(card);
					}
					if(_status.event.goon){
						return 8-get.value(card);
					}
					if(!ui.selected.cards.length){
						return 7-get.value(card);
					}
					return 0;
				}).set('goon',goon).set('att',att);
				'step 1'
				if(result.bool){
					player.logSkill('shanhe_huisheng',trigger.source);
					game.delay();
					event.num=result.cards.length;
					var goon=false;
					if(event.num>2||get.attitude(trigger.source,player)>=0){
						goon=true;
					}
					var forced=false;
					var str='获得其中一张牌并防止伤害';
					if(trigger.source.countCards('he')<event.num){
						forced=true;
					}
					else{
						str+='，或取消并弃置'+get.cnNumber(result.cards.length)+'张牌';
					}
					trigger.source.chooseButton([str,result.cards],forced).set('ai',function(button){
						if(_status.event.goon){
							return get.value(button.link);
						}
						return get.value(button.link)-8;
					}).set('goon',goon);
				}
				else{
					event.finish();
				}
				'step 2'
				if(result.bool){
					var card=result.links[0];
					trigger.source.gain(card,player,'giveAuto','bySelf');
					trigger.cancel();
					if(!player.storage.shanhe_huisheng) player.storage.shanhe_huisheng=[];
					player.storage.shanhe_huisheng.push(trigger.source);
				}
				else{
					trigger.source.chooseToDiscard(event.num,true,'he');
				}
				}
			},
