			Shanhe_miji: {
	        	trigger: { player: "phaseJieshuBegin" },
	        	filter(event, player) {
		     	return player.isDamaged();
	        	},
	        	async content(event, trigger, player) {
		    	let num = player.getDamagedHp();
		    	await player.draw(num);
			    if (player.countCards("he") && game.hasPlayer(target => target != player)) {
			    	if (_status.connectMode) {
				    	game.broadcastAll(() => (_status.noclearcountdown = true));
			    	}
			    	let given_map = [];
			    	while (num > 0 && player.hasCard(card => !card.hasGaintag("olsujian_given"), "he") && game.hasPlayer(current => current != player)) {
				    	const result = await player.chooseCardTarget({
							filterCard(card, player) {
								return !card.hasGaintag("olsujian_given");
							},
							selectCard: [1, num],
							position: "he",
							filterTarget: lib.filter.notMe,
							prompt: "秘计：请选择要分配的卡牌和目标",
							prompt2: "（还可分配" + num + "张）",
							ai1(card) {
								return !ui.selected.cards.length && card.name == "du" ? 1 : 0;
							},
							ai2(target) {
								const player = get.event().player;
								const card = ui.selected.cards[0];
								if (card) {
									return get.value(card, target) * get.attitude(player, target);
								}
								return 0;
							},
							allowChooseAll: true,
						}).forResult();
				    	if (result?.cards?.length && result.targets?.length) {
					    	const {
						    	cards,
						    	targets: [target],
					    	} = result;
					    	num -= cards.length;
					    	if (given_map.some(i => i[0] == target)) given_map[given_map.indexOf(given_map.find(i => i[0] == target))][1].addArray(cards); 
					    	else given_map.push([target, cards]);
					    	player.addGaintag(cards, "olsujian_given");
					    } 
					    else break;
			    	}
			    	if (_status.connectMode) {
				    	game.broadcastAll(() => {
						    delete _status.noclearcountdown;
					    	game.stopCountChoose();
				    	});
			    	}
			    	if (given_map.length) {
				    	await game.loseAsync({
							gain_list: given_map,
							player: player,
							cards: given_map.slice().flatMap(list => list[1]),
							giver: player,
							animate: "giveAuto",
						}).setContent("gaincardMultiple");
			     	}
		    	}
	        	},
        	},
