            "Nianshou_baozhu":{//爆竹🧨机制
                init:function (player){
                    player.Baozhu=0;
	                if(!player.Nianshou_baozhu) player.Nianshou_baozhu=30; //获取初始爆竹
	                player.storage.Nianshou_baozhu=player.Nianshou_baozhu;
	                player.update();
	                if(!game.Nianshou) game.Nianshou=game.findPlayer(function(current){return current.hasClan('年兽')&&(current!=player&&player.getEnemies().includes(current))});
            	},
            	mark:true,
                marktext:"🧨",
                intro:{
                    name:"爆竹",
                    content:'mark',
                },
            	trigger:{player:'useCard'},
                forced:true,
                charlotte:true,
                popup:false,
                firstDo:true,
                filter:function(event,player){
                return player.isPhaseUsing()&&typeof get.number(event.card)=='number';
                },
                content:function(){
                "step 0"
                var goon=false;
                event.num=Math.min(get.number(trigger.card),13);//防止超过13点的牌
                if(event.num>=player.Nianshou_baozhu){
                    goon=true;
                    event.num2=event.num-player.Nianshou_baozhu;
                    player.Nianshou_baozhu=30-event.num2;
                }
                else player.Nianshou_baozhu-=event.num;
	            player.storage.Nianshou_baozhu=player.Nianshou_baozhu;
	            player.update();
                if(goon==true){
                    if(event.num2==0){
                        if(game.Nianshou){
                            player.logSkill("Nianshou_baozhu",game.Nianshou);
                            game.Nianshou.damage('fire',30*(1+(player.Baozhu|0)),player);
                            event.mubiao=player.getFriends(function(current){return current.hasCard(function(card){return get.number(card)==event.num&&lib.filter.canBeDiscarded(card,current,current)},'he')}).sortBySeat(lib.updateCurrentPhase(player));
                        }
                        player.Baozhu+=Math.min(1,3-player.Baozhu);
                    }
                    else{
                        player.damage('fire',player);
                        player.draw(2);
                        player.Baozhu=0;
                    }
                }
                else event.finish();
                "step 1"
                if(event.mubiao&&event.mubiao.length>0) event.count=0;
                else event.finish();
                "step 2"
                event.mubiao[event.count].chooseToDiscard('弃置一张点数为'+get.translation(event.num)+'的牌一起引爆。','he',function(card){return get.number(card)==event.num}).set('ai',function(card){return true}).logSkill='Nianshou_baozhu';
                "step 3"
                if(result.bool){
                    if(game.Nianshou){
                        event.mubiao[event.count].line(game.Nianshou,'green');
                        game.Nianshou.damage('fire',30*(1+(event.mubiao[event.count].Baozhu|0)),event.mubiao[event.count]);
                    }
                    event.mubiao[event.count].Baozhu+=Math.min(1,3-event.mubiao[event.count].Baozhu);
                }
                "step 4"
                event.count++;
                "step 5"
                if(event.count<event.mubiao.length) event.goto(2);
                },
                mod:{
                    aiOrder:function(player,card,num){
                        if(get.number(card)==player.storage.Nianshou_baozhu) return num+100;
                        if(get.number(card)<player.storage.Nianshou_baozhu) return num+1;
                    },
                },
            },
