                if(result.control=='十周年年兽') event.boss=["nianshoudashu","nianshoudawei","nianshoudawu","nianshoudaqun","xishoudashu","xishoudawei","xishoudawu","xishoudaqun","nianshoudashu1","nianshoudawei1","nianshoudawu1","xishoudawei1","xishoudawu1","xishoudaqun1","nianshouweishu","nianshouweiwu","nianshoushuwu","nianshoushuqun","nianshouweiqun","nianshouwuqun"];
                event.xuanze=[];
