                boss_shengxiao=["olsx_zishu","Olsx_chouniu","Olsx_yinhu","Olsx_maotu","Olsx_chenlong","Olsx_sishe","Olsx_wuma","olsx_weiyang","olsx_shenhou","olsx_youji","olsx_xugou","olsx_haizhu"];
                game.shengxiao=[];
