            boss_qice:{
				enable:'phaseUse',
				usable:1,
				audio:'boss_qice_backup',
				filter:function(event,player){
					var hs=player.getCards('h');
					if(!hs.length) return false;
					for(var i=0;i<hs.length;i++){
						var mod2=game.checkMod(hs[i],player,'unchanged','cardEnabled2',player);
					if(mod2===false) return false;
					}
					return true;
				},
				chooseButton:{
					dialog:function(player){
						var list=[];
						for(var i=0;i<lib.inpile.length;i++){
							if(get.type(lib.inpile[i])=='trick') list.push(['锦囊','',lib.inpile[i]]);
						}
						return ui.create.dialog(get.translation('boss_qice'),[list,'vcard']);
					},
					filter:function(button,player){
						return lib.filter.filterCard({name:button.link[2]},player,_status.event.getParent());
					},
					check:function(button){
						var player=_status.event.player;
						var recover=0,lose=1,players=game.filterPlayer();
						for(var i=0;i<players.length;i++){
							if(players[i].hp==1&&get.damageEffect(players[i],player,player)>0&&!players[i].hasSha()){
								return (button.link[2]=='juedou')?2:-1;
							}
							if(!players[i].isOut()){
								if(players[i].hp<players[i].maxHp){
									if(get.attitude(player,players[i])>0){
										if(players[i].hp<2){
											lose--;
											recover+=0.5;
										}
										lose--;
										recover++;
									}
									else if(get.attitude(player,players[i])<0){
										if(players[i].hp<2){
											lose++;
											recover-=0.5;
										}
										lose++;
										recover--;
									}
								}
								else{
									if(get.attitude(player,players[i])>0){
										lose--;
									}
									else if(get.attitude(player,players[i])<0){
										lose++;
									}
								}
							}
						}
						if(lose>recover&&lose>0) return (button.link[2]=='nanman')?1:-1;
						if(lose<recover&&recover>0) return (button.link[2]=='taoyuan')?1:-1;
						return (button.link[2]=='wuzhong')?1:-1;
					},
					backup:function(links,player){
						return {
							filterCard:true,
							selectCard:-1,
							position:'h',
							audio:2,
							popname:true,
							viewAs:{name:links[0][2]},
						}
					},
					prompt:function(links,player){
						return '将全部手牌当作'+get.translation(links[0][2])+'使用';
					}
				},
				ai:{
					order:1,
					result:{
						player:function(player){
							var num=0;
							var cards=player.getCards('h');
							if(cards.length>=3&&player.hp>=3&&!player.hasSkill("shanhe_lianying")) return 0;
							for(var i=0;i<cards.length;i++){
								num+=Math.max(0,get.value(cards[i],player,'raw'));
							}
							num/=cards.length;
							num*=Math.min(cards.length,player.hp);
							return 12-num+(player.hasSkill("shanhe_lianying")?5:0)+(player.hasSkill("shanhe_hezhong")?2:0);
						}
					},
					threaten:1.6,
				},
			},
			boss_qice_backup:{},
