            "boss_liushi":{
                audio:"ext:活动BOSS/audio/skill:2",
                enable:"phaseUse",
                filter:function(event,player){
                    return player.countCards('he',{suit:'heart'})>0;
                },
                filterCard:{
                    suit:"heart",
                },
                position:"he",
                filterTarget:function(card,player,target){
                    return player.canUse('sha',target,false);
                },
                check:function(card){
                    var player=_status.event.player;
                    var next=player.getNext();
                    var att=get.attitude(player,next);
                    if(att>0){
                        var js=next.getCards('j');
                        if(js.length) return get.judge(js[0])+10-get.value(card);
                        return 9-get.value(card)
                    }
                    return 6-get.value(card);
                },
                discard:false,
                prepare:"throw",
                loseTo:"cardPile",
                visible:true,
                insert:true,
                content:function(){
                game.log(player,'将',cards,'置于牌堆顶'); 
                player.useCard({name:'sha',isCard:true},false,targets).card.boss_liushi=true;
                },
                group:"boss_liushi_damage",
                subSkill:{
                    damage:{
                        trigger:{
                            source:"damageSource",
                        },
                        forced:true,
                        popup:false,
                        filter:function(event,player){
                        return event.card&&event.card.boss_liushi==true&&event.player.isAlive()&&event.getParent(3).name=='boss_liushi';
                        },
                        content:function(){
                        trigger.player.addMark('boss_liushi2',1);
                        trigger.player.addSkill('boss_liushi2');
                        },
                        sub:true,
                    },
                },
                ai:{
                    order:function(){
                        return get.order({name:'sha'})-0.4;
                    },
                    result:{
                        target:function(player,target){
                            var eff=get.effect(target,{name:'sha'},player,target);
                            var damageEff=get.damageEffect(target,player,player);
                            if(eff>0) return damageEff>0?0:eff;
                            if(target.hasSkill('bagua_skill')||target.hasSkill('rw_bagua_skill')||target.hasSkill('bazhen')) return 0;
                            return eff;
                        },
                    },
                },
            },
