            "boss_zhanwan":{
                audio:"ext:活动BOSS/audio/skill:2",
                trigger:{
                    global:"phaseDiscardEnd",
                },
                forced:true,
                filter:function(event,player){
                return event.player.hasSkill('boss_liushi2')&&event.player.getHistory('lose',function(evt){
                    if(evt.type=='discard'&&evt.getParent('phaseDiscard')==event) return true;
                }).length>0;
                },
                logTarget:"player",
                content:function(){
                trigger.player.removeSkill('boss_liushi2');
                var num=0;
                trigger.player.getHistory('lose',function(evt){
                    if(evt.type=='discard'&&evt.getParent('phaseDiscard')==trigger) num+=evt.cards2.length;
                });
                player.draw(num);
                },
            },
            "wenhe_sidao":{
                audio:"ext:活动BOSS/audio/skill:2",
                trigger:{
                    player:"useCardEnd",
                },
                filter:function(event,player){
                if(event.getParent(2).name=='wenhe_sidao') return false;
                if(player.hasSkill('wenhe_sidaoy')||!player.countCards('hs')) return false;
                if(!event.targets||!event.targets.length||!event.isPhaseUsing(player)) return false;
                var history=player.getHistory('useCard');
                var index=history.indexOf(event)-1;
                if(index<0) return false;
                var evt=history[index];
                if(!evt||!evt.targets||!evt.targets.length||!evt.isPhaseUsing(player)) return false;
                for(var i=0;i<event.targets.length;i++){
                    if(evt.targets.includes(event.targets[i])&&lib.filter.filterTarget({name:'shunshou'},player,event.targets[i])) return true;
                }
                return false;
                },
                direct:true,
                content:function(){
                var targets=player.getLastUsed(1).targets;
                var next=player.chooseToUse();
                next.set('targets',game.filterPlayer(function(current){return targets.includes(current)&&trigger.targets.includes(current)}));
                next.set('openskilldialog',get.prompt2('wenhe_sidao'));
                next.set('norestore',true);
                next.set('_backupevent','wenhe_sidaox');
                next.set('custom',{
                    add:{},
                    replace:{window:function(){}}
                });
                next.backup('wenhe_sidaox');
                },
            },
