            "ns_bianshen":{
                init:function(player){
                if(!player.storage.ns_bianshen){
                player.storage.ns_bianshen=['jingjue','ruizhi','baonu'];
                }
                },
                marktext:"变",
                mark:true,
                ruleSkill:true,
                locked:true,
                intro:{
                    name:"变身",
                    content:function(storage,player){
                    var map={
                        jingjue:'警觉',
                        ruizhi:'睿智',
                        baonu:'暴怒'
                    };
                    if(player.storage.ns_bianshen2&&player.storage.ns_bianshen3) return '下一个状态：'+map[player.storage.ns_bianshen_next];
                    return '下一个状态：未知'; 
                    },
                },
                trigger:{
                   player:"phaseBefore",
                },
                forced:true,
                charlotte:true,
                popup:false,
                ruleSkill:true,
                filter:function(event,player){
                return (player.name1=='ol_old_nianshou'||player.name2=='ol_old_nianshou')||(player.name1=='ol_old_nianshou1'||player.name2=='ol_old_nianshou1')||(player.name1=='ol_old_nianshou2'||player.name2=='ol_old_nianshou2')||(player.name1=='ol_old_nianshou3'||player.name2=='ol_old_nianshou3');
                },
                content:function(){
                "step 0"
                if(!player.storage.ns_bianshen_next) player.storage.ns_bianshen_next=player.storage.ns_bianshen.randomGet();
                player.markSkill('ns_bianshen');
                "step 1"
                if(player.storage.ns_bianshen_previous) player.removeSkill('ns_'+player.storage.ns_bianshen_previous);
                player.addSkill('ns_'+player.storage.ns_bianshen_next);
                player.storage.ns_bianshen_previous=player.storage.ns_bianshen_next;
                player.storage.ns_bianshen.remove(player.storage.ns_bianshen_next);
                if(!player.storage.ns_bianshen1) player.storage.ns_bianshen1=player.storage.ns_bianshen_next;
                switch(player.storage.ns_bianshen_next){
					case 'jingjue':
					player.addAdditionalSkill('ns_jingjue',["nianshou_jingti","nianshou_jingkong"]);
					break;
					case 'ruizhi':
					player.addAdditionalSkill('ns_ruizhi',['nianshou_ruya','nianshou_boxue']);
					break;
					case 'baonu':
					player.addAdditionalSkill('ns_baonu',['nianshou_kuangbao','nianshou_shouyi']);
					break;
				}
                player.update();
                "step 2"
                if(!player.storage.ns_bianshen.length){
                    player.storage.ns_bianshen=['jingjue','ruizhi','baonu'];
                    player.storage.ns_bianshen_next=player.storage.ns_bianshen1;
                }
                else{
                    if(!player.storage.ns_bianshen2) player.storage.ns_bianshen_next=player.storage.ns_bianshen.randomGet();
                    else player.storage.ns_bianshen_next=player.storage.ns_bianshen.includes(player.storage.ns_bianshen2)?player.storage.ns_bianshen2:player.storage.ns_bianshen3?player.storage.ns_bianshen3:player.storage.ns_bianshen.randomGet();
                } 
                player.update();
                "step 3"
                if(!player.storage.ns_bianshen2) player.storage.ns_bianshen2=player.storage.ns_bianshen_next;
                else if(!player.storage.ns_bianshen3) player.storage.ns_bianshen3=player.storage.ns_bianshen_next;
                player.update();
                },
                derivation:["nianshou_ruya","nianshou_boxue","nianshou_jingti","nianshou_jingkong","nianshou_kuangbao","nianshou_shouyi"],
            },  
