            fenghuo_sheyan:{
				trigger:{target:'useCardToTarget'},
				filter:function(event,player){
					if(!event.targets||!event.targets.includes(player)) return false;
					var info=get.info(event.card);
					if(info.type!='trick') return false;
					if(info.multitarget) return false;
					if(event.targets.length>1) return true;
					return game.hasPlayer(function(current){
						return !event.targets.includes(current)&&lib.filter.targetEnabled2(event.card,event.player,current);
					});
				},
				direct:true,
				content:function(){
				'step 0'
				var bool1=(trigger.targets.length>1);
				var bool2=game.hasPlayer(function(current){
					return !trigger.targets.includes(current)&&lib.filter.targetEnabled2(trigger.card,trigger.player,current);
				});
				if(bool1&&bool2){
					player.chooseControlList(get.prompt('fenghuo_sheyan'),['为'+get.translation(trigger.card)+'增加一个目标','为'+get.translation(trigger.card)+'减少一个目标'],function(event,player){
						if(_status.event.add) return 0;
						return 1;
					}).set('add',get.effect(player,trigger.card,trigger.player,player)>=0);
				}
				else if(bool2){
					event.type='add';
					event.goto(2);
					event.unchosen=true;
				}
				else{
					event.type='remove';
					event.goto(2);
					event.unchosen=true;
				}
				'step 1'
				if(result.control=='cancel2'){
					event.finish();
				}
				else if(result.index==1){
					event.type='remove';
				}
				else{
					event.type='add';
				}
				'step 2'
				if(event.type=='add'){
					player.chooseTarget(event.unchosen?get.prompt('fenghuo_sheyan'):null,'为'+get.translation(trigger.card)+'增加一个目标',function(card,player,target){
						var trigger=_status.event.getTrigger();
						return !trigger.targets.includes(target)&&lib.filter.targetEnabled2(trigger.card,trigger.player,target);
					}).set('ai',function(target){
						var trigger=_status.event.getTrigger();
						return get.effect(target,trigger.card,trigger.player,_status.event.player);
					});
				}
				else{
					player.chooseTarget(event.unchosen?get.prompt('fenghuo_sheyan'):null,'为'+get.translation(trigger.card)+'减少一个目标',function(card,player,target){
						return _status.event.targets.includes(target);
					}).set('ai',function(target){
						var trigger=_status.event.getTrigger();
						return -get.effect(target,trigger.card,trigger.player,_status.event.player);
					}).set('targets',trigger.targets);
				}
				'step 3'
				if(result.bool){
					if(!event.isMine()&&!event.isOnline()) game.delayx();
					event.target=result.targets[0];
				}
				else{
					event.finish();
				}
				'step 4'
				player.logSkill('fenghuo_sheyan',event.target);
				if(event.type=='add'){
					trigger.targets.push(event.target);
				}
				else{
					trigger.getParent().excluded.add(event.target);
				}
				},
				ai:{
					expose:0.2
				},
			},
