            "danji_yonglue":{
                trigger:{
                   global:"phaseJudgeBegin",
                },
                direct:true,
                filter:function(event,player){
                return event.player!=player&&event.player.countDiscardableCards(player,'j')>0;
                },
                content:function(){
                'step 0'
                var att=get.attitude(player,trigger.player);
                var nh=trigger.player.countCards('h');
                var eff=get.effect(trigger.player,{name:'sha',isCard:true},player,player);
                if(player.inRange(trigger.player)||!player.canUse({name:'sha',isCard:true},trigger.player,false)) eff=0;
                player.discardPlayerCard(get.prompt('danji_yonglue',trigger.player),trigger.player,'j').set('ai',function(button){
                var name=button.link.viewAs||button.link.name;
                var att=_status.event.att;
                var nh=_status.event.nh;
                var eff=_status.event.eff;
                var trigger=_status.event.getTrigger();
                if(att>0&&eff>=0) return 1;
                if(att>=0&&eff>0) return 1;
                if(att>0&&(trigger.player.hp>=3||trigger.player.getEquip('bagua')||trigger.player.countCards('h','shan'))){
                if(name=='lebu'&&nh>trigger.player.hp) return 1;
                if(name=='bingliang'&&nh<trigger.player.hp) return 1;
                }
                return 0;
                }).set('att',att).set('nh',nh).set('eff',eff).set('logSkill',['danji_yonglue',trigger.player]);
                'step 1'
                if(result.bool){
                    if(!player.inRange(trigger.player)&&player.canUse({name:'sha',isCard:true},trigger.player,false)) player.useCard({name:'sha',isCard:true},trigger.player);
                    else player.draw();
                }
                },
            },
            shanhe_chenshuo:{
				trigger:{player:'phaseJieshuBegin'},
				direct:true,
				filter:function(event,player){
					return player.countCards('h')>0;
				},
				hasSame:function(info,card){
					if(info.type==get.type2(card,false)) return true;
					if(info.suit!='none'&&info.suit==get.suit(card,false)) return true;
					if(typeof info.number=='number'&&info.number>0&&info.number==get.number(card,false)) return true;
					return info.length==get.cardNameLength(card)
				},
				content:function(){
				'step 0'
				player.chooseCard('h',get.prompt('shanhe_chenshuo'),'展示一张手牌，然后展示并获得牌堆顶的牌').set('ai',function(card){
					if(get.type(card)=='basic') return 1+Math.random();
					return Math.random();
				})
				'step 1'
				if(result.bool){
					player.logSkill('shanhe_chenshuo');
					player.showCards(result.cards,get.translation(player)+'发动了【谶说】');
					var card=result.cards[0];
					event.cardInfo={
						type:get.type2(card,player),
						suit:get.suit(card,player),
						number:get.number(card,player),
						length:get.cardNameLength(card),
					}
					event.cards=[];
					event.forceDie=true;
					event.includeOut=true;
				}
				else event.finish();
				'step 2'
				var judgestr=get.translation(player)+'展示的第'+get.cnNumber(cards.length+1,true)+'张【谶说】牌';
				event.videoId=lib.status.videoId++;
				var card=get.cards()[0];
				event.card=card;
				cards.add(card);
				game.cardsGotoOrdering(card);
				game.addVideo('judge1',player,[get.cardInfo(card),judgestr,event.videoId]);
				game.broadcastAll(function(player,card,str,id,cardid){
					var event;
					if(game.online){
						event={};
					}
					else{
						event=_status.event;
					}
					if(game.chess){
						event.node=card.copy('thrown','center',ui.arena).addTempClass('start');
					}
					else{
						event.node=player.$throwordered(card.copy(),true);
					}
					if(lib.cardOL) lib.cardOL[cardid]=event.node;
					event.node.cardid=cardid;
					event.node.classList.add('thrownhighlight');
					ui.arena.classList.add('thrownhighlight');
					event.dialog=ui.create.dialog(str);
					event.dialog.classList.add('center');
					event.dialog.videoId=id;
				},player,card,judgestr,event.videoId,get.id());
				game.log(player,'展示了牌堆顶的',card);
				game.delay(2);
				'step 3'
				game.broadcastAll(function(id){
					var dialog=get.idDialog(id);
					if(dialog){
						dialog.close();
					}
					ui.arena.classList.remove('thrownhighlight');
				},event.videoId);
				game.addVideo('judge2',null,event.videoId);
				if(cards.length<3&&player.isIn()&&lib.skill.shanhe_chenshuo.hasSame(event.cardInfo,card)) event.goto(2);
				else{
					game.broadcastAll(function(){ui.clear()});
					player.gain(cards,'gain2');
				}
				},
			},
