            "shanhe_guixin":{
				trigger: {
				   player: "damageEnd"
				},
				filter(event, player) {
                return game.hasPlayer((cur) => {return cur !== player && cur.countCards("hej") > 0});
                },
                check(event, player) {
                if (player.isTurnedOver() || event.num > 1) return true;
                var num = game.countPlayer(function(current) {
                if (current.countCards("he") && current != player && get.attitude(player, current) <= 0) return true;
                if (current.countCards("j") && current != player && get.attitude(player, current) > 0) return true;
                });
                return num >= 2;
                },
                getIndex(event, player) {
                return event.num;
                },
                async content(event, trigger, player) {
                let targets = game.filterPlayer().sortBySeat(lib.updateCurrentPhase(player));
				targets.remove(player);
                player.line(targets, "green");
                const control = await player.chooseControl("手牌区", "装备区", "判定区").set("ai", function() {
                if (game.hasPlayer(function(current) {return current.countCards("j") && current != player && get.attitude(player, current) > 0})) return 2;
                return Math.floor(Math.random() * 3);
                }).set("prompt", "请选择优先获得的区域").forResult();
                const range = {
                    手牌区: ["h", "e", "j"],
                    装备区: ["e", "h", "j"],
                    判定区: ["j", "h", "e"]
                }[control.control || "手牌区"];
                while (targets.length > 0) {
                    const target = targets.shift();
                    for (var i = 0; i < range.length; i++) {
                        var cards2 = target.getCards(range[i]);
                        if (cards2.length) {
                            var card = cards2.randomGet();
                            await player.gain(card, target, "giveAuto", "bySelf");
                            break;
                        }
                    }
                }
                await player.turnOver();
                },
                ai: {
                    maixie: true,
                    maixie_hp: true,
                    threaten(player, target) {
                        if (target.hp == 1) return 2.5;
                        return 1;
                    },
                    effect: {
                        target(card, player, target) {
                            if (!target._shanhe_guixin_eff && get.tag(card, "damage") && target.hp > (player.hasSkillTag("damageBonus", true, {card,target}) ? 2 : 1)) {
                                if (player.hasSkillTag("jueqing", false, target)) return [1, -2];
                                target._shanhe_guixin_eff = true;
                                let gain = game.countPlayer(function(current) {
                                if (target == current) return 0;
                                if (get.attitude(target, current) > 0) {
                                    if (current.hasCard((cardx) => lib.filter.canBeGained(cardx, target, current, "shanhe_guixin") && get.effect(current, cardx, current, current) < 0, "j")) return 1.3;
                                    return 0;
                                }
                                if (current.hasCard((cardx) => lib.filter.canBeGained(cardx, target, current, "shanhe_guixin") && get.effect(current, cardx, current, current) > 0, "e")) return 1.1;
                                if (current.hasCard((cardx) => lib.filter.canBeGained(cardx, target, current, "shanhe_guixin"), "h")) return 0.9;
                                return 0;
                                });
                                if (target.isTurnedOver()) gain += 2.3; 
                                else gain -= 2.3;
                                delete target._shanhe_guixin_eff;
                                return [1, Math.max(0, gain)];
                            }
                        }
                    }
                }
            },
