                'step 14'
                game.addVideo('reinit2',player,player.name);
                game.addGlobalSkill('hezong_zjzl');
                game.boss.markSkill("hezong_zjzl");
                game.boss.chat('你要知道，有些人就是为乱世而生的');
                var content = ['本局事件', get.translation("hezong_zjzl"),get.translation("hezong_zjzl"+'_info')];
                game.me.chooseControl('ok').set('dialog', content);
                event.goto(19);
                'step 15'
