                game.addBossFellow(game.me==game.boss?1:7,"hezong_daqin_baiqi"); 
                game.addBossFellow(game.me==game.boss?7:5,"hezong_daqin_shangyang");
                game.addBossFellow(game.me==game.boss?6:4,"hezong_daqin_zhangyi"); 
                'step 18'
                game.addVideo('reinit2',player,player.name);
                game.addGlobalSkill("hezong_hslh");
                game.boss.markSkill("hezong_hslh");
                game.hezong_hslh=true;
                var list=[];
