	                var targets=game.filterPlayer(function(current){return (current==game.boss||game.boss.getFriends().includes(current))}).sortBySeat(lib.updateCurrentPhase(player));
	                if(targets&&targets.length>0){
	                    for(var i=0;i<targets.length;i++){
	                        targets[i].maxHp-=Math.floor(targets[i].maxHp/2);
                            targets[i].update();
                        }
	                }
