            "whtn_fuhuo":{
                trigger:{
                   global:"dieAfter",
                },
                fixed:true,
				popup:false,
				direct:true,
				firstDo:true,
				unique:true,
				forced:true,
				forceDie:true,
				noLose:true,
				locked:true,
				noRemove:true,
				noDeprive:true,
				noDisable:true,
				charlotte:true,
				globalFixed:true,
				superCharlotte:true,
				ruleSkill:true,
                filter:function(event,player,name){
                if(game.boss!=player) return false;
                event.targets=[];
                for(var i=0;i<game.dead.length;i++){
                    if(!game.dead[i].hasSkill("wenhe_taoni")&&!game.dead[i].hasSkill("wenhe_taonia")&&!game.dead[i].hasSkill("wenhe_taonib")&&get.attitude(player,game.dead[i])>0&&game.dead[i].parentNode==player.parentNode&&lib.IsSameCamp(player, game.dead[i])) event.targets.push(game.dead[i]);
                } 
                return event.targets&&event.targets.length>0;
                },
                content:function(){
                'step 0'
                event.targets=[];
                for(var i=0;i<game.dead.length;i++){
                    if(!game.dead[i].hasSkill("wenhe_taoni")&&!game.dead[i].hasSkill("wenhe_taonia")&&!game.dead[i].hasSkill("wenhe_taonib")&&get.attitude(player,game.dead[i])>0&&game.dead[i].parentNode==player.parentNode&&lib.IsSameCamp(player, game.dead[i])) event.targets.push(game.dead[i]);
                } 
                'step 1'
                if(event.targets.length){
                var target=event.targets.shift();
                event.suicong=["hulaoguan_tanlangjun","hulaoguan_feixiongjun","hulaoguan_baolvejun","hulaoguan_fengyaojun","hulaoguan_hubenjun","hulaoguan_longxiangjun"];
                event.suicong.remove(target.name);
                var players=game.filterPlayer();
                for(var i=0;i<players.length;i++){
                     event.suicong.remove(players[i].name);
                     event.suicong.remove(players[i].name1);
                     event.suicong.remove(players[i].name2);
                }
                target.init(event.suicong.randomGet());
                target.maxHp=(_status.whlw==1?3:(_status.whlw==2?5:_status.whlw==5?4:8));
                target.update();
				target.revive(target.maxHp);
				var list=['equip1','equip2','equip3','equip4','equip5'];
                for(var i=0;i<list.length;i++){
                    if(!target.isDisabled(list[i])) list.splice(i--,1);
                    else target.enableEquip(list[i]);
                }
				target.draw(_status.whlw==1?2:(_status.whlw==2?3:4));
				event.redo();
                }
                },                
            },
