					if(player.hasCard(function(card){return get.type(card)!='basic'&&get.value(card)<7&&lib.filter.cardDiscardable(card,player,'shanhe_zengou')},'eh')) return true;
					return player.hp>Math.max(1,event.player.hp)||(get.effect(player,{name:'losehp'},player,player)>=0&&player.hp+player.countCards('h','tao')>3);
