			shanhe_jieming:{
				trigger:{player:['damageEnd','die']},
				direct:true,
				forceDie:true,
				filter:function(event,player){
					if(event.name=='die') return true;
					return player.isIn();
				},
				content:function(){
				'step 0'
				event.count=trigger.num||1;
				'step 1'
				event.count--;
				player.chooseTarget(get.prompt2('shanhe_jieming'),function(card,player,target){
					return target.maxHp>0;
				}).set('ai',function(target){
					var att=get.attitude(_status.event.player,target);
					var draw=Math.min(5,target.maxHp)-target.countCards('h');
					if(draw>=0){
						if(target.hasSkillTag('nogain')) att/=6;
						if(att>2){
							return Math.sqrt(draw+1)*att;
						}
						return att/3;
					}
					if(draw<-1){
						if(target.hasSkillTag('nogain')) att*=6;
						if(att<-2){
							return -Math.sqrt(1-draw)*att;
						}
					}
					return 0;
				});
				'step 2'
				if(result.bool){
					var target=result.targets[0];
					event.target=target;
					player.logSkill('shanhe_jieming',target);
					target.draw(Math.min(5,target.maxHp));
				}
				else event.finish();
				'step 3'
				var num=target.countCards('h')-Math.min(5,target.maxHp);
				if(num>0) target.chooseToDiscard('h',true,num);
				'step 4'
				if(event.count>0&&player.isIn()&&player.hasSkill('shanhe_jieming')) event.goto(1);
				},
				ai:{
					expose:0.2,
					maixie:true,
					maixie_hp:true,
					effect:{
						target:function(card,player,target,current){
							if(get.tag(card,'damage')&&target.hp>1){
								if(player.hasSkillTag('jueqing',false,target)&&get.tag(card,'damage')) return [1,-2];
								var max=0;
								var players=game.filterPlayer();
								for(var i=0;i<players.length;i++){
									if(get.attitude(target,players[i])>0){
										max=Math.max(Math.min(5,players[i].hp)-players[i].countCards('h'),max);
									}
								}
								switch(max){
									case 0:return 2;
									case 1:return 1.5;
									case 2:return [1,2];
									default:return [0,max];
								}
							}
							if((card.name=='tao'||card.name=='caoyao')&&
								target.hp>1&&target.countCards('h')<=target.hp) return [0,0];
						}
					},
				}
			},
