            "shanhe_huangkong":{
                trigger:{
                   player:["phaseDrawBegin2",'phaseDiscardBefore'],
                },
                forced:true,
                filter:function(event,player,name){
                if(name=='phaseDrawBegin2') return !event.numFixed;
                else return true;
                },
                content:function(){
                var name=event.triggername;
                if(name=='phaseDrawBegin2') trigger.num*=2;
                if(name=='phaseDiscardBefore'){
                if (player.storage.originalNeedsToDiscard) player.needsToDiscard = player.storage.originalNeedsToDiscard;
                if (!player.storage.originalNeedsToDiscard) player.storage.originalNeedsToDiscard = player.needsToDiscard;
                player.needsToDiscard = function(add, filter, pure) {
                    var num = player.storage.originalNeedsToDiscard.call(this, add, filter, pure);
                    return num * 2;
                };
                player.when({player:"phaseDiscardEnd"}).assign({firstDo: true}).then(()=>{player.needsToDiscard = player.storage.originalNeedsToDiscard});
                }
                },
                ai:{
                    nokeep:true,
                    skillTagFilter:function(player,tag,arg){
						if(tag=='nokeep'){
							if(!player.isPhaseUsing()||!player.needsToDiscard()) return false;
						}
					},
                },
            },			           
