            "shanhe_lianzhang":{
                global:'shanhe_zhang',
                trigger:{
                   player:"damageEnd",
                },
                frequent:true,
                filter:function(event,player){
                return player.getDamagedHp()>0&&game.hasPlayer(function(current){return current!=player&&player.getEnemies().includes(current)});
                },
                logTarget:function(event,player){return game.filterPlayer(function(current){return current!=player&&player.getEnemies().includes(current)}).sortBySeat(lib.updateCurrentPhase(player));
                },
                content:function(){
                var targets=game.filterPlayer(function(current){return (current!=player&&player.getEnemies().includes(current))}).sortBySeat(lib.updateCurrentPhase(player));
	            for(var target of targets){
		            target.damage('nocard',(player.getDamagedHp()|0));
		            if((player.getDamagedHp()|0)>0){
		                target.addMark('shanhe_zhang',(player.getDamagedHp()|0));
		                target.addSkill('shanhe_zhang');
		            }
	            }
                },
                ai:{
                    threaten: function(player, target) {
                        let hpRatio = player.hp / player.maxHp;
                        let dmg = player.getDamagedHp() || 0;
                        return 0.4 + (1 - hpRatio) * 0.3 + dmg * 0.2; 
                    },
                    maixie:true,
                    "maixie_defend":true,
                    effect:{
						target: function(card, player, target) {
						    if (get.tag(card, 'damage')) {
                                if (player.hasSkillTag('jueqing', false, target)) return [1, -2]; 
                                if (!target.getFriends().length) return; 
                                let baseDmg = player.getDamagedHp() || 0;
                                let dmgFactor = (target.getDamagedHp() + (target.hujia || 0) > 0) ? 0 : 1;
                                let hpLimit = Math.max(0, target.maxHp - 1);
                                let coreValue = 2 * Math.min(dmgFactor, hpLimit);
                                let skillBonus = 0;
                                if (target.hasSkill("shanhe_chengxiong")) skillBonus = (game.roundNumber % 2 !== 0) ? 1 : -1;
                                let enemyCount = target.getEnemies().length;
                                let finalScore = enemyCount * (coreValue + skillBonus)
                                return [1, finalScore];
                            }
                        }
					}
                },
            },            
