			shanhe_fangzhu:{
				trigger:{player:'damageEnd'},
				direct:true,
				content:function(){
				"step 0"
				var draw=player.getDamagedHp();
				player.chooseTarget(get.prompt('shanhe_fangzhu'),'令一名其他角色翻面'+(draw>0?'并摸'+get.cnNumber(draw)+'张牌':''),function(card,player,target){return player!=target}).setHiddenSkill('shanhe_fangzhu').set('ai',target=>{
					if(target.hasSkillTag('noturn')) return 0;
					var player=_status.event.player;
					var current=_status.currentPhase;
					var dis=current?get.distance(current,target,'absolute'):1;
					var draw=player.getDamagedHp();
					var att=get.attitude(player,target);
					if(att==0) return target.hasJudge('lebu')?Math.random()/3:Math.sqrt(get.threaten(target))/5+Math.random()/2;
					if(att>0){
						if(target.isTurnedOver()) return att+draw;
						if(draw<4) return -1;
						if(current&&target.getSeatNum()>current.getSeatNum()) return att+draw/3;
						return 10*Math.sqrt(Math.max(0.01,get.threaten(target)))/(3.5-draw)+dis/(2*game.countPlayer());
					}
					else{
						if(target.isTurnedOver()) return att-draw;
						if(draw>=5) return -1;
						if(current&&target.getSeatNum()<=current.getSeatNum()) return -att+draw/3;
						return (4.25-draw)*10*Math.sqrt(Math.max(0.01,get.threaten(target)))+2*game.countPlayer()/dis;
					}
				});
				"step 1"
				if(result.bool){
					player.logSkill('shanhe_fangzhu',result.targets);
					var draw=player.getDamagedHp();
					if(draw>0) result.targets[0].draw(draw);
					result.targets[0].turnOver();
				}
				},
				ai:{
					maixie:true,
					maixie_hp:true,
					effect:{
						target:function(card,player,target){
							if(get.tag(card,'damage')){
								if(player.hasSkillTag('jueqing',false,target)&&get.tag(card,'damage')) return [1,-2];
								if(target.hp<=1) return;
								if(!target.hasFriend()) return;
								var hastarget=false;
								var turnfriend=false;
								var players=game.filterPlayer();
								for(var i=0;i<players.length;i++){
									if(get.attitude(target,players[i])<0&&!players[i].isTurnedOver()){
										hastarget=true;
									}
									if(get.attitude(target,players[i])>0&&players[i].isTurnedOver()){
										hastarget=true;
										turnfriend=true;
									}
								}
								if(get.attitude(player,target)>0&&!hastarget) return;
								if(turnfriend||target.hp==target.maxHp) return [0.5,1];
								if(target.hp>1) return [1,0.5];
							}
						}
					}
				}
			},
