			"TX_hongyan":{
                locked:true,
				mod: {
                    suit: function(card) {
                        if (card.suit == 'spade' || card.suit == 'club') return 'heart';
                    },
                    color: function(card) {
                        if (card.color == 'black') return 'red';
                    },
                },
			},
			TX_fencheng: {
                skillAnimation: "epic",
                animationColor: "gray",
                audio: "xinfencheng",
                enable: "phaseUse",
                filterTarget(card, player, target) {
                return player != target;
                },
                limited: true,
                selectTarget: -1,
                multitarget: true,
                multiline: true,
                line: "fire",
                async content(event, trigger, player) {
                player.awakenSkill(event.name);
                player.addSkill("TX_fencheng2");
                const targets = event.targets.toSorted(lib.sort.seat);
                let num = 1;
                for (const target of targets) {
                const res = get.damageEffect(target, player, target, "fire");
                const result = await target.chooseToDiscard({
                prompt: `弃置至少${get.cnNumber(num)}张牌或受到2点火焰伤害`,
                selectCard: [num, Infinity],
                position: "he",
                allowChooseAll: true,
                ai(card) {
                    if (ui.selected.cards.length >= get.event().num) return -1;
                    if (_status.event.player.hasSkillTag("nofire")) return -1;
                    if (_status.event.res >= 0) return 6 - get.value(card);
                    if (get.type(card) != "basic") return 10 - get.value(card);
                    return 8 - get.value(card);
                }
                }).set("res", res).set("num", num).forResult();
                if (result.bool && result.cards?.length) num = result.cards.length + 1; 
                else {
                    await target.damage({
                        num: 2,
                        nature: "fire"
                    });
                    num = 1;
                }
                }
                },
                ai: {
                    order: 1,
                    result: {
                        player(player) {
                            var num = 0, eff = 0, players = game.filterPlayer(function(current) {return current != player}).sortBySeat(player);
                            for (var target of players) {
                                if (get.damageEffect(target, player, target, "fire") >= 0) {
                                    num = 0;
                                    continue;
                                }
                                var shao = false;
                                num++;
                                if (target.countCards("he", function(card) {
                                    if (get.type(card) != "basic") return get.value(card) < 10;
                                    return get.value(card) < 8;
                                }) < num) shao = true;
                                if (shao) {
                                    eff -= 4 * (get.realAttitude || get.attitude)(player, target);
                                    num = 0;
                                } 
                                else eff -= num * (get.realAttitude || get.attitude)(player, target) / 4;
                            }
                            if (eff < 4) return 0;
                            return eff;
                        }
                    }
                }
            },
