			shezhan_zongxuan:{
			    audio:'zongxuan',
				trigger:{
					player:'loseAfter',
					global:'loseAsyncAfter',
				},
				filter:function(event,player){
					if(!game.hasPlayer(current=>current!=player)) return false;
					if(event.type!='discard'||event.getlx===false) return false;
					var evt=event.getl(player);
					if(!evt||!evt.cards2) return false;
					for(var i=0;i<evt.cards2.length;i++){
						if(get.position(evt.cards2[i])=='d'){
							return true;
						}
					}
					return false;
				},
				direct:true,
				content:function(){
				'step 0'
				if(trigger.delay==false) game.delay();
				event.cards=[];
				var cards2=trigger.getl(player).cards2;
				for(var i=0;i<cards2.length;i++){
					if(get.position(cards2[i],true)=='d'){
						event.cards.push(cards2[i]);
					}
				}
				if(_status.connectMode) game.broadcastAll(function(){_status.noclearcountdown=true});
				event.given_map={};
				'step 1'
				var goon=false;
				for(var i=0;i<event.cards.length;i++){
					if(event.cards[i].name=='du'){
						goon=true;break;
					}
				}
				if(!goon){
					goon=game.hasPlayer(function(current){
						return current!=player&&get.attitude(player,current)>1;
					});
				}
				player.chooseButton(['【纵玄】：是否令一名其他角色获得其中一张弃置的牌？',event.cards],1).set('ai',function(button){
					if(_status.event.goon&&ui.selected.buttons.length==0) return Math.abs(9-get.value(button.link))-1;
					return 0;
				}).set('goon',goon);
				'step 2'
				if(result.bool){
					event.cards.removeArray(result.links);
					event.togive=result.links.slice(0);
					player.chooseTarget('选择一名其他角色获得'+get.translation(result.links),true,lib.filter.notMe).set('ai',function(target){return -get.attitude(_status.event.player,target)*target.countCards('he')});
				}
				else event.finish();
				'step 3'
				if(result.bool&&result.targets&&result.targets.length){
					var id=result.targets[0].playerid,map=event.given_map;
					if(!map[id]) map[id]=[];
					map[id].addArray(event.togive);
				}
				'step 4'
				if(_status.connectMode){
					game.broadcastAll(function(){delete _status.noclearcountdown;game.stopCountChoose()});
				}
				var list=[],targets=[];
				for(var i in event.given_map){
					var source=(_status.connectMode?lib.playerOL:game.playerMap)[i];
					list.push([source,event.given_map[i]]);
					targets.push(source);
				}
				if(targets.length){
				    event.target=targets[0];
					player.logSkill('shezhan_zongxuan',targets);
					game.loseAsync({
						gain_list:list,
						giver:player,
						animate:'gain2',
					}).setContent('gaincardMultiple');
				}
				else event.finish();
				'step 5'
				if(event.target.countGainableCards(player,'he')>0) player.gainPlayerCard(event.target,'he',[1,2]);
				},
			},
