            shanhe_chongshen: {
	        	locked: false,
	        	enable: "chooseToUse",
	        	filterCard(card) {
		    	return get.itemtype(card) == "card" && card.hasGaintag("shanhe_chongshen") && get.color(card) == "red";
	        	},
	        	position: "h",
	        	viewAs: { name: "shan" },
	        	viewAsFilter(player) {
		        	if (!player.countCards("h", card => card.hasGaintag("shanhe_chongshen") && get.color(card) == "red")) return false;
	        	},
	        	prompt: "将本轮得到的红色牌当作【闪】使用",
	        	check(card) {
		        	return 7 - get.value(card);
	         	},
	        	ai: {
	        		order: 2,
		        	respondShan: true,
		        	skillTagFilter(player, tag, arg) {
			        	if (arg == "respond" || !player.countCards("h", card => _status.connectMode || (card.hasGaintag("shanhe_chongshen") && get.color(card) == "red"))) return false;
		        	},
		        	effect: {
			        	target(card, player, target, current) {
				        	if (get.tag(card, "respondShan") && current < 0) return 0.6;
			        	},
		        	},
	         	},
	        	group: "shanhe_chongshen_mark",
	        	mod: {
		        	aiValue(player, card, num) {
			        	if (get.name(card) != "shan" && get.itemtype(card) == "card" && (!card.hasGaintag("shanhe_chongshen") || get.color(card) != "red")) return;
			        	let cards = player.getCards("hs", card => get.name(card) == "shan" || card.hasGaintag("shanhe_chongshen"));
			        	cards.sort((a, b) => (get.name(b) == "shan" ? 1 : 2) - (get.name(a) == "shan" ? 1 : 2));
			        	const geti = () => {
				        	if (cards.includes(card)) return cards.indexOf(card);
				        	return cards.length;
			        	};
			        	if (get.name(card) == "shan") return Math.min(num, [6, 4, 3][Math.min(geti(), 2)]) * 0.6;
			        	return Math.max(num, [6.5, 4, 3][Math.min(geti(), 2)]);
		        	},
		        	aiUseful() {
			        	return lib.skill.shanhe_chongshen.mod.aiValue.apply(this, arguments);
		        	},
	        	},
	        	init(player) {
		        	if (game.phaseNumber > 0) {
			        	const hs = player.getCards("h"),
			        		history = player.getAllHistory();
			        	let cards = [];
			        	for (let i = history.length - 1; i >= 0; i--) {
			        		for (const evt of history[i].gain) {
					        	cards.addArray(evt.cards);
				        	}
				        	if (history[i].isRound) break;
			        	}
			        	cards = cards.filter(i => hs.includes(i));
			        	if (cards.length) player.addGaintag(cards, "shanhe_chongshen");
		        	}
	        	},
	        	onremove(player) {
		        	player.removeGaintag("shanhe_chongshen");
	        	},
	        	subSkill: {
		        	mark: {
			        	charlotte: true,
			        	trigger: { player: "gainBegin", global: "roundStart" },
			         	filter(event, player) {
			    		return event.name == "gain" || game.roundNumber > 1;
			        	},
			        	forced: true,
		        		popup: false,
			        	content() {
			    		if (trigger.name == "gain") trigger.gaintag.add("shanhe_chongshen");
			    		else player.removeGaintag("shanhe_chongshen");
			        	},
		        	},
		        },
        	},
