            jiange_tianyun:{
				trigger:{player:'phaseJieshuBegin'},
				direct:true,
				filter:function(event,player){
				return game.hasPlayer(function(current){return current!=player&&player.getEnemies().includes(current)});
				},
				content:function(){
				"step 0"
				event.forceDie=true;
				player.chooseTarget('请选择【天陨】的目标','选择一名敌方角色，失去1点体力，然后令其随机受到2~3点火焰伤害并弃置装备区里的所有牌',function(card,player,target){return target!=player&&player.getEnemies().includes(target)}).set('ai',function(target){
			    	if(player.hp<=1) return 0;
					if(get.attitude(player,target)>-3) return 0;
					var eff=[2,3].randomGet()*get.damageEffect(target,player,player,'fire');
					if(eff>0){
						return eff+target.countCards('e')/2;
					}
					return 0;
				});
				"step 1"
				if(result.bool){
					player.logSkill('jiange_tianyun',result.targets,'fire');
					player.loseHp();
					event.target=result.targets[0];
				}
				else event.finish();
				"step 2"
				if(event.target){
			        player.addExpose(0.15);
			     	event.target.damage('nocard',[2,3].randomGet(),'fire');
				}
				else event.finish();
				"step 3"
				if(event.target){
					var es=event.target.getCards('e');
					if(es.length){
						event.target.discard(es);
					}
				}
				},
				ai:{
					threaten:2,
					fireAttack:true,
				},
			},
            "shidian_lunhui":{
                trigger:{
                    player:"phaseZhunbeiBegin",
                },
                audio:"ext:活动BOSS/audio/skill:true",
                forced:true,
                direct:true,
                filter:function(event,player){
                return player.hp<=2&&game.hasPlayer(function(current){return current!=player&&current.hp>2&&player.getEnemies().includes(current)});
                },
                content:function(){
                'step 0'
                if(game.countPlayer(function(current){return (current!=player&&current.hp>2&&player.getEnemies().includes(current))&&!game.hasPlayer(function(current2){return current2.hp>current.hp&&player.getEnemies().includes(current2)})})==1){
                    var target=game.findPlayer(function(current){return (current!=player&&current.hp>2&&player.getEnemies().includes(current))&&!game.hasPlayer(function(current2){return current2.hp>current.hp&&player.getEnemies().includes(current2)})});
                    player.logSkill('shidian_lunhui',target);
                    var hp1=player.hp;
                    var hp2=target.hp;
                    var next=player.recover(Math.min(player.maxHp,hp2)-hp1)&&target.loseHp(hp2-Math.min(target.maxHp,hp1));
			    	next._triggered=null;
                    player.update();
                    target.update();
                    game.log(player,'和',target,'交换了体力值')
                    event.finish();
                }
                else player.chooseTarget(true,'请选择【轮回】的目标','选择一名敌方角色，与其交换体力值',function(card,player,target){return (target!=player&&target.hp>2&&player.getEnemies().includes(target))&&!game.hasPlayer(function(target2){return target2.hp>target.hp&&player.getEnemies().includes(target2)})}).set('forceDie',true).set('ai',function(target){
			        return -get.attitude(_status.event.player,target)*target.hp;
			    });
                'step 1'
                if(result.bool){
                    var target=result.targets[0];
                    player.logSkill('shidian_lunhui',target);
                    var hp1=player.hp;
                    var hp2=target.hp;
                    var next=player.recover(Math.min(player.maxHp,hp2)-hp1)&&target.loseHp(hp2-Math.min(target.maxHp,hp1));
			    	next._triggered=null;
                    player.update();
                    target.update();
                    game.log(player,'和',target,'交换了体力值')
                }
                },
                mod:{
			        aiOrder(player, card, num) {
			            if(_status.dying.length||!game.hasPlayer(function(current){return current!=player&&player.getFriends().includes(current)})) return; //无队友时不考虑控血
				        if(card.name=="tao"&&player.isPhaseUsing()&&!player.needsToDiscard()&&player.hp>0) return 0;
			        },
		        },
		        ai:{
					threaten:function(player,target){
						if(player.hp>2) return 0.5;
						return 2;
					},
					maixie:true,
					effect:{
					    target:function(card,player,target,current){
					        if(get.tag(card,'damage')&&(!target.hasFriend()||(!game.hasPlayer(function(current){return current!=target&&current.hp>2&&target.getEnemies().includes(current)})))) return;
					        if(get.tag(card,'recover')&&_status.dying.length) return;
					        if(get.tag(card,'damage')&&Math.max(get.tag(card,'damage'),(_status.event.baseDamage|0))==1&&target.hp==3&&!target.isTurnedOver()&&_status.currentPhase!=target&&get.distance(_status.currentPhase,target,'absolute')<=3) return [0.5,1];
					        if(get.tag(card,'recover')&&target.hp<=2&&!target.isTurnedOver()&&_status.currentPhase!=target&&get.distance(_status.currentPhase,target,'absolute')<=2) return [1,-3];
					    }
				    },	
				},
            },
