            "hulaoguan_boss_wumou":{
                audio:"ext:活动BOSS/audio/skill:2",
                getfilter: card => card.name !== "juedou" || get.number(card) === "unsure" || !card?.cards?.length || card?.cards?.length > 1 || lib.card[card.cards[0].name].type !== "trick",
                trigger:{
                   global:"useCardToBegin",
                },
                forced:true,
                logTarget:function(trigger,player,name){
                return player==trigger.player?trigger.target:trigger.player;
                },
                filter:function(event,player,name){
                return event.card&&event.card.name=='juedou'&&(event.player==player||event.target==player)&&!event.getParent().excluded.contains(event.target)&&event.player.hp!=event.target.hp;
                },
                content:function(){
                var upper=trigger.target.hp>trigger.player.hp?trigger.target:trigger.player;
                var lower=trigger.target.hp<trigger.player.hp?trigger.target:trigger.player;
                var lowId = lower.playerid;
                if (!trigger.shaReq) trigger.shaReq = {};
                trigger.shaReq[lowId] = (trigger.shaReq[lowId] || 1) + 1; 
                lower.when({global:"damageBegin1"}).filter(evt=>{return evt.card&&evt.card.name=='juedou'&&evt.source&&evt.player&&evt.source==lower&&evt.player==upper&&evt.card==trigger.card}).assign({firstDo: true}).then(()=>{trigger.num++});
                },
                mod:{
                    cardname(card) {
			         	const event = get.event();
			        	if (!["chooseToUse", "chooseToRespond"].includes(event.name)) return;
			         	if (lib.card[card.name].type === "trick" && !_status._hulaoguan_boss_wumou_check) return "juedou";
		        	},
			        cardnature:function(card,player){
						if(['trick'].includes(lib.card[card.name].type)) return false;
					},
					cardEnabled: function(card, player) {
                        if (card.name == 'juedou' && card.cards && card.cards[0]) {
                            var originalCard = card.cards[0];
                            if (get.type(originalCard) == 'trick' && !get.subtype(originalCard)) {
                                var info = lib.card[originalCard.name];
                                if (info && typeof info.filterTarget === 'function') {
                                    if (!game.hasPlayer(function(current) { return info.filterTarget(card, player, current)&&game.hasPlayer(function(current){return lib.filter.targetEnabled2(card,player,current)&&lib.filter.targetInRange(card,player,current)})&&player.canUse({name:'juedou'},current); })) return false; 
                                }
                                if (info.notarget == true) return false;
                            }
                        }
                    },
                    playerEnabled:function(card,player,target){
                        if (card.name == 'juedou' && card.cards && card.cards[0]) {
                            var originalCard = card.cards[0];
                            var info = lib.card[originalCard.name];
                            if (info && info.range && typeof info.range.global === 'number') {
                                if (get.distance(player, target) > info.range.global) return false;
                            }
                            if (get.type(originalCard) == 'trick' && !get.subtype(originalCard)) {
                                var info = lib.card[originalCard.name];
                                if (info && typeof info.filterTarget === 'function') {
                                    if (!info.filterTarget(card, player, target)) return false;
                                }
                            }
                        }
                    },
					selectTarget: function(card, player, range) {
                        if (card.name == 'juedou' && card.cards && card.cards[0]) {
                            var originalCard = card.cards[0];
                            if (get.type(originalCard) == 'trick' && !get.subtype(originalCard)) {
                                var info = lib.card[originalCard.name];
                                var select = info ? info.selectTarget : undefined;
                                var min = 1, max = 1;
                                if (select != undefined) {
                                    if (typeof select == "number") {
                                        min = select; max = select;
                                    } 
                                    else if (Array.isArray(select)) {
                                        min = select[0]; max = select[1];
                                    }
                                }
                                range[0] = min;
                                range[1] = max;
                            }
                        }
                    },
					aiValue: (player, card, val) => {
					    if (card.name == 'wuxie') return 0;
                        if (card.name !== 'juedou' || !card.cards || !card.cards[0]) return val; 
                        var originalCard = card.cards[0];
                        var info = lib.card[originalCard.name];
                        if (!info || typeof info.filterTarget !== 'function') return 0;
                        if (info.notarget === true) return 0;
                        var hasValidTarget = game.hasPlayer(function(current) {
                            if (!info.filterTarget(card, player, current)) return false;
                            if (!lib.filter.targetEnabled2(card, player, current)) return false;
                            if (!lib.filter.targetInRange(card, player, current)) return false;
                            if (!player.canUse({ name: 'juedou' }, current)) return false;
                            return true; 
                        });
                        if (!hasValidTarget) return 0;
                        return val;
                    },
                    aiUseful: (player, card, val) => {
                        if (card.name == 'wuxie') return 0;
                        if (card.name !== 'juedou' || !card.cards || !card.cards[0]) return val; 
                        var originalCard = card.cards[0];
                        var info = lib.card[originalCard.name];
                        if (!info || typeof info.filterTarget !== 'function') return 0;
                        if (info.notarget === true) return 0;
                        var hasValidTarget = game.hasPlayer(function(current) {
                            if (!info.filterTarget(card, player, current)) return false;
                            if (!lib.filter.targetEnabled2(card, player, current)) return false;
                            if (!lib.filter.targetInRange(card, player, current)) return false;
                            if (!player.canUse({ name: 'juedou' }, current)) return false;
                            return true; 
                        });
                        if (!hasValidTarget) return 0;
                        return val;
                    },
				},
				ai: {
					halfneg: true,
				},
            },
