            "shanhe_zhengu":{
				trigger: { player: "phaseJieshuBegin" },
                filter(event, player) {
                return game.hasPlayer((current) => current != player);
                },
                async cost(event, trigger, player) {
                event.result = await player.chooseTarget(get.prompt2(event.skill), lib.filter.notMe).set("ai", (target) => {
                    const player2 = get.player();
                    const num = Math.min(5, player2.countCards("h")) - target.countCards("h");
                    const att = get.attitude(player2, target);
                    return num * att;
                }).forResult();
                },
                async content(event, trigger, player) {
                const target = event.targets[0];
                player.addSkill("shanhe_zhengu_mark");
                player.markAuto("shanhe_zhengu_mark", [target]);
                },
                async sync(player, target) {
                const num = player.countCards("h");
                const num2 = target.countCards("h");
                if (num < num2) {
                    await target.chooseToDiscard(num2 - num, true, "h", "allowChooseAll");
                } 
                else {
                    await target.drawTo(Math.min(5, num));
                }
                },
                subSkill: {
                    mark: {
                        charlotte: true,
                        onremove: true,
                        intro: { content: "你的回合结束时和$的下个回合结束时，其将手牌摸至或弃置至与你手牌数相同（至多摸至五张）" },
                        trigger: { global: "phaseEnd" },
                        filter(event, player) {
                        if (player == event.player) return player.getStorage("shanhe_zhengu_mark").some((current) => current.isIn());
                        return player.getStorage("shanhe_zhengu_mark").includes(event.player);
                        },
                        forced: true,
                        popup: false,
                        logTarget(event, player) {
                        return player == event.player ? player.getStorage("shanhe_zhengu_mark").filter((current) => current.isIn()).sortBySeat() : event.player;
                        },
                        async content(event, trigger, player) {
                        if (player == trigger.player) {
                            for (const target of event.targets.sortBySeat()) {
                                if (!target.isIn()) continue;
                                await lib.skill.shanhe_zhengu.sync(player, target);
                            }
                        } 
                        else {
                            const target = event.targets[0];
                            player.unmarkAuto(event.name, [target]);
                            if (!player.getStorage(event.name).length) player.removeSkill(event.name);
                            await lib.skill.shanhe_zhengu.sync(player, target);
                        }
                        }
                    }
                }
			},
