			fenghuo_qinyin:{
				trigger:{player:'phaseDiscardEnd'},
				direct:true,
				filter:function(event,player){
					var cards=[];
					player.getHistory('lose',function(evt){
						if(evt.type=='discard'&&evt.getParent('phaseDiscard')==event) cards.addArray(evt.cards2);
					});
					return cards.length>1;
				},
				content:function(){
					"step 0"
					event.forceDie=true;
					if(typeof event.count!='number'){
						// event.count=trigger.cards.length-1;
						event.count=1;
					}
					var recover=0,lose=0,players=game.filterPlayer();
					for(var i=0;i<players.length;i++){
						if(players[i].hp<players[i].maxHp){
							if(get.attitude(player,players[i])>0){
								if(players[i].hp<2){
									lose--;
									recover+=0.5;
								}
								lose--;
								recover++;
							}
							else if(get.attitude(player,players[i])<0){
								if(players[i].hp<2){
									lose++;
									recover-=0.5;
								}
								lose++;
								recover--;
							}
						}
						else{
							if(get.attitude(player,players[i])>0){
								lose--;
							}
							else if(get.attitude(player,players[i])<0){
								lose++;
							}
						}
					}
					var prompt=get.prompt('fenghuo_qinyin')+'（剩余'+get.cnNumber(event.count)+'次）';
					player.chooseControl('失去体力','回复体力','cancel2',ui.create.dialog(get.prompt('fenghuo_qinyin'),'hidden')).ai=function(){
						if(lose>recover&&lose>0) return 0;
						if(lose<recover&&recover>0) return 1;
						return 2;
					}
					"step 1"
					if(result.control=='cancel2'){
						event.finish();
					}
					else{
						player.logSkill('fenghuo_qinyin');
						event.bool=(result.control=='回复体力');
						event.num=0;
						event.players=game.filterPlayer();
					}
					"step 2"
					if(event.num<event.players.length){
						var target=event.players[event.num];
						if(event.bool){
							target.recover(player);
						}
						else{
							target.loseHp();
						}
						event.num++;
						event.redo();
					}
					"step 3"
					if(event.count>1){
						event.count--;
						event.goto(0);
					}
				},
				ai:{
					expose:0.1,
					threaten:2
				}
			},
			fenghuo_danshou:{
				trigger:{
					global:'phaseJieshuBegin',
					target:'useCardToTargeted',
				},
				direct:true,
				filter:function(event,player,name){
					return ((name=='phaseJieshuBegin'&&event.player!=player&&player.countDiscardableCards(player,'he')>=event.player.countCards('h'))||(event.targets&&event.targets.includes(player)&&['basic','trick'].includes(get.type(event.card,'trick'))))&&!player.hasSkill('fenghuo_danshou_as');
				},
				content:function(){
				'step 0'
				if(event.triggername=='phaseJieshuBegin'){
					var num=trigger.player.countCards('h');
					if(num>0) player.chooseToDiscard(get.prompt('fenghuo_danshou',trigger.player),num,'弃置'+get.cnNumber(num)+'张牌并对'+get.translation(trigger.player)+'造成1点伤害','he').set('logSkill',['fenghuo_danshou',trigger.player]).set('ai',function(card){
						if(get.damageEffect(_status.event.getTrigger().player,_status.event.player,_status.event.player)>0) return Math.max(5.5,8-_status.event.selectTarget)-get.value(card);
						return -1;
					});
					else player.chooseBool(get.prompt('fenghuo_danshou',trigger.player),'对'+get.translation(trigger.player)+'造成1点伤害').ai=function(){
						return get.damageEffect(trigger.player,player,player)>0
					};
				}
				else{
					var num=0;
					game.countPlayer2(function(current){
						var history=current.getHistory('useCard');
						for(var j=0;j<history.length;j++){
							if(['basic','trick'].includes(get.type(history[j].card,'trick'))&&history[j].targets&&history[j].targets.includes(player)) num++;
						}
					});
					event.num=num;
					player.chooseBool(get.prompt('fenghuo_danshou')+'（可摸'+get.cnNumber(num)+'张牌）',get.translation('fenghuo_danshou_info')).set('ai',function(){
						return _status.event.choice;
					}).set('choice',function(){
						if(player.isPhaseUsing()){
							if(player.countCards('h',function(card){
								return ['basic','trick'].includes(get.type(card,'trick'))&&player.canUse(card,player,null,true)&&get.effect(player,card,player)>0&&player.getUseValue(card,null,true)>0;
							})) return false;
							return true;
						}
						if(num>2) return true;
						var card=trigger.card;
						if(get.tag(card,'damage')&&player.hp<=trigger.getParent().baseDamage&&(!get.tag(card,'respondShan')||player.countCards('h','shan')==0)&&(!get.tag(card,'respondSha')||player.countCards('h','sha')==0)) return true;
						var source=_status.currentPhase,todis=(source.countCards('h')-Math.max(0,source.needsToDiscard()));
						if(todis<=Math.max(Math.min(2+(source.hp<=1?1:0),player.countCards('he',function(card){
							return get.value(card,player)<Math.max(5.5,8-todis)
						})),player.countCards('he',function(card){
							return get.value(card,player)<=0;
						}))&&get.damageEffect(source,player,player)>0) return false;
						if(!source.isPhaseUsing()||get.attitude(player,source)>0) return true;
						if(card.name=='sha'&&!source.getCardUsable('sha')) return true;
						return Math.random()<num/3;
					}());
				}
				'step 1'
				if(result.bool){
					if(!result.cards||!result.cards.length){
						player.logSkill('fenghuo_danshou',trigger.player);
					}
					if(event.triggername=='useCardToTargeted'){
						player.draw(num);
						player.addTempSkill('fenghuo_danshou_as');
					}
					else{
						trigger.player.damage('nocard');
					}
					}
				},
				subSkill:{as:{sub:true}},
				ai:{
					threaten:0.6,
					effect:{
						target:function(card,player,target,current){
							if(typeof card!='object'||target.hasSkill('fenghuo_danshou_as')||!['basic','trick'].includes(get.type(card,'trick'))) return;
							var num=0;
							game.countPlayer2(function(current){
								var history=current.getHistory('useCard');
								for(var j=0;j<history.length;j++){
									if(['basic','trick'].includes(get.type(history[j].card,'trick'))&&history[j].targets&&history[j].targets.includes(player)) num++;
								}
							});
							if(player==target&&current>0) return [1.1,num];
							return [0.9,num];
						},
					},
				},
			},
