            "syzlb_lianjun":{
                marktext:"联军",
                mark:true,
                intro:{
                name:"联军",
                content:"你阵亡后，若当前回合结束后仍有联军在场，你回到战场，并将体力值回复至3点，摸三张牌",
                },
                locked:true,
                trigger:{
                    global:"phaseEnd",
                },
                forced:true,
                charlotte:true,
                direct:true,
                filter:function(event,player){
                var list=[];
                for(var i=0;i<game.dead.length;i++){
                    list.push(game.dead[i].name);
                }
                return list.length>0; 
                },
                content:function(){
                'step 0'
                event.targets=[];
                var dead=game.dead.slice(0);
                for(var i=0;i<dead.length;i++){
                    if(get.attitude(player,game.dead[i])>0&&dead[i].parentNode==player.parentNode&&lib.IsSameCamp(player, game.dead[i])&&dead[i].hasSkill("syzlb_lianjun")){
                event.targets.push(dead[i]);
                }
                }    
                'step 1'
                if(event.targets.length){
                    var target=event.targets.shift();
                    target.revive(3);
                    target.draw(3);
                    event.redo();
                }
                'step 2'
                game.delay();
                },
                popup:false,
            },
