	        "hlaz_huanren":{
                mode:["boss"],
                trigger:{
                   global:["roundStart","dieAfter"],
                   player:"dieBegin",
                },
                firstDo:true,
                fixed:true,
                direct:true,
                unique:true,
                forced:true,
                forceDie:true,
                noLose:true,
                locked:true,
                noRemove:true,
                noDeprive:true,
                noDisable:true,
                charlotte:true,
                globalFixed:true,
                superCharlotte:true,
                filter:function(event,player,name){
                if (_status.hlaz_level == undefined || _status.hlaz_level >= 2) return false;
                if(name=="roundStart") return (player.isFriendOf(game.boss)||player==game.boss)&&game.roundNumber==3;
                if(name=="dieBegin"||name=="dieAfter") return (player.isFriendOf(game.boss)||player==game.boss);
                },
                content:function(){
                'step 0'
                var name=event.triggername;
                if(name=="roundStart"){
                    player.ShenWei=true;
                    player.discard(player.getCards('hej'));
					player.link(false);
					player.turnOver(false);
					_status.hlaz_level++;
                }
                if(name=="dieBegin"){
                    var num=0;
                    for(var i=1;i<6;i++){
                        if(player.isDisabled(i)) num++;
                    }
                    if(num<2) player.KuangBao=true;
                    var list=['equip1','equip2','equip3','equip4','equip5'];
                    for(var i=0;i<list.length;i++){
                        if(!player.isDisabled(list[i])) list.splice(i--,1);
                        else player.enableEquip(list[i]);
                    }
                    event.finish();
                }
                if(name=="dieAfter"){
                    _status.hlaz_level++;
                    if(trigger.player!=player){
                        player.ShenWei=true;
                        player.discard(player.getCards('hej'));
				    	player.link(false);
				    	player.turnOver(false);
                    }
                }
                'step 1'
                var list=['equip1','equip2','equip3','equip4','equip5'];
                for(var i=0;i<list.length;i++){
                    if(!player.isDisabled(list[i])) list.splice(i--,1);
                    else player.enableEquip(list[i]);
                }
                
                // while(_status.event.name!="phaseLoop"){
		       	// _status.event=_status.event.parent;
          	    // }
	       	   	// game.resetSkills();
	      	    // _status.paused=false;
			    
	            //终止阶段
                for (var phase of lib.phaseName) {
                var evt = event.getParent(phase);
                if (evt?.name === phase && !evt.finished) {
                //不触发cancelled时机
                game.log(_status.currentPhase,"结束了", phase);
                evt.cancel(true, null, true);
                break;
                }
                }
                
                //终止回合
                var evt = event.getParent("phase", true);
                if (evt) {
                    game.log(evt.player, "结束了回合");
                    evt.num = evt.phaseList.length;
                    evt.goto(12);
                }
                
                'step 2'
                player.init(player.ShenWei==true?"hulaoguan_boss_shenweifeijiang_lvbu":(player.KuangBao?"hulaoguan_boss_nuyanfentian_lvbu":"hulaoguan_boss_molinyuansou_lvbu"));
                if(!player.isAlive()) player.revive(player.maxHp);
                player.hp=player.maxHp;
                player.update();
                player.draw(4);
                _status.currentPhase=player;
                if(player.KuangBao) player.tempBanSkill("hulaoguan_boss_shenfen"); //解决奇怪的进场bug
                game.delay(0.5);
	            game.addVideo('reinit2',player,player.name);
	            
	            'step 3'
	            var evt = _status.event.getParent("phaseLoop", true);
		    	if (evt) {
					game.resetSkills();
					var evtx = _status.event;
					while (evtx != evt) {
						evtx.finish();
						evtx.untrigger(true);
						evtx = evtx.getParent();
					}
					evtx.player = player;
					evtx.step = 0;
				}
				
				game.roundNumber--;
				
				if (game.bossinfo) {
					game.bossinfo.loopType = 1;
					_status.roundStart = game.boss;
				}
                },
            },
