            liezhuan_qingjiao:{
				trigger:{player:'phaseUseBegin'},
				filter:function(event,player){
					if(!ui.cardPile.hasChildNodes()&&!ui.discardPile.hasChildNodes());
					var hs=player.getCards('h');
					if(!hs.length) return false;
					for(var i of hs){
						if(!lib.filter.cardDiscardable(i,player,'liezhuan_qingjiao')) return false;
					}
					return true;
				},
				check:function(event,player){
				    return player.countCards('h')<=7;
				},
				content:function(){
				'step 0'
				player.chooseToDiscard(true,'h',player.countCards('h'));
				'step 1'
				var evt=trigger.getParent();
				if(evt&&evt.getParent&&!evt.liezhuan_qingjiao){
					evt.liezhuan_qingjiao=true;
					var next=game.createEvent('liezhuan_qingjiao_discard',false,evt.getParent());
					next.player=player;
					next.setContent(function(){
						var hs=player.getCards('he');
						if(hs.length) player.discard(hs);
					});
				}
				'step 2'
				var list=[];
				var typelist=[];
				var getType=function(card){
					var sub=get.subtype(card);
					if(sub) return sub;
					return card.name;
				};
				for(var i=0;i<ui.cardPile.childElementCount;i++){
					var node=ui.cardPile.childNodes[i];
					var typex=getType(node);
					if(!typelist.includes(typex)){
						list.push(node);
						typelist.push(typex);
						if(list.length>=8) break;
					}
				}
				if(list.length<8){
					for(var i=0;i<ui.discardPile.childElementCount;i++){
						var node=ui.discardPile.childNodes[i];
						var typex=getType(node);
							if(!typelist.includes(typex)){
							list.push(node);
							typelist.push(typex);
							if(list.length>=8) break;
						}
					}
				}
				player.gain(list,'gain2');
				},
			},
