            "honglian_skill":{
                equipSkill:true,
                trigger:{
                   player:"phaseEnd",
                },           
                check:function (event,player){
	            return game.hasPlayer(function(current){return player.getEnemies().includes(current)&&current.countDiscardableCards(player,'he')>0});
	            },
	            filter:function(event,player){
                return game.hasPlayer(function(current){return player.getEnemies().includes(current)&&current.countDiscardableCards(player,'he')>0});
                },
                logTarget:function(event,player){
                return game.filterPlayer(function(current){return current!=player&&player.getEnemies().includes(current)&&current.countDiscardableCards(player,'he')>0}).sortBySeat(lib.updateCurrentPhase(player));
                },
                content:function (){
                "step 0" 
                event.basic=0;
                event.trick=0;
                event.equip=0;
                var targets=game.filterPlayer(function(current){return (current!=player&&player.getEnemies().includes(current)&&current.countDiscardableCards(player,'he'))}).sortBySeat(lib.updateCurrentPhase(player));
	            for(var target of targets){
	                var hs=target.getCards('he').randomGet();
		            target.discard(hs).set('discarder',player).set('delay',false);
		            if(get.type2(hs)=='basic') event.basic++;
                    if(get.type2(hs)=='trick') event.trick++;
                    if(get.type2(hs)=='equip') event.equip++;
	            }
                "step 1" 
                player.draw(2*event.basic);
                "step 2"       
                if(event.trick>0) event.count1=event.trick;
                else event.goto(6);
                "step 3"
                var target=player.getEnemies(function(current){return current.countGainableCards(player,'he')}).randomGet();
                if(target) player.gain(target.getCards('he').randomGet(),target,'giveAuto');
                "step 4"      
                event.count1--;
                "step 5"    
                if(event.count1>0) event.goto(3);
                "step 6"         
                if(event.equip>0) event.count2=event.equip;
                else event.finish();
                "step 7"
                var target=game.filterPlayer(function(current){return player.getEnemies().includes(current)}).randomGet();
                if(target) target.loseHp();
                "step 8"      
                event.count2--;
                "step 9"    
                if(event.count2>0) event.goto(7);
                },
            },
