            shanhe_fenglve:{
				trigger:{
					player:"phaseUseBegin",
				},
				direct:true,
				filter:function(event,player){
					if(player.countCards('h')==0) return false;
					return game.hasPlayer(function(current){
						return player.canCompare(current);
					});
				},
				content:function(){
				'step 0'
				var goon=player.hasCard(function(card){
			    	if(get.position(card)!="h") return false;
			    	var val=get.value(card);
			    	if(val<0) return true;
			    	if(val<=5) return card.number>=12;
			    	if(val<=6) return card.number>=13;
			    	return false;
				});
				player.chooseTarget(get.prompt2('shanhe_fenglve'),function(card,player,target){return player.canCompare(target)}).set('ai', function(target) {
				    if (!_status.event.goon) return 0;
				    var target_valuable_cards = target.countCards('e') + target.countCards('j');
				    var attitude = get.attitude(player, target);
				    if (attitude < 0) {
                        var enemy_card_count = target.countCards('h');
                        return (-attitude) * (1 + target_valuable_cards) * (1 + enemy_card_count * 0.5);
                    }
                    return 0; 
                }).set('goon',goon);
				'step 1'
				event.cards=[]; //记录
				if(result.bool){
					var target=result.targets[0];
					event.target=target;
					player.logSkill('shanhe_fenglve',target);
					player.chooseToCompare(target);
				}
				else event.finish();
				'step 2'
				if(result.bool){
				    event.gainner=player;
					event.giver=event.target;
					if(event.giver.countCards('h')){ //手牌
						event.giver.choosePlayerCard(event.giver,Math.min(3,event.giver.countCards('h')),'h',true).set('prompt','选择交给'+get.translation(event.gainner)+'的牌');
				    }
				    else event.goto(4);
				}
				else{
					if(player.countCards('he')){
						event.gainner=target;
						event.giver=player;
						player.choosePlayerCard(player,true,'he').set('prompt','选择交给'+get.translation(event.gainner)+'的牌');
						event.goto(9);
					}
					else event.finish();
				}
				'step 3'
				if (result.links) event.cards.push(...result.links);
			    'step 4'
			    if(event.giver.countCards('e')){ //装备
				    event.giver.choosePlayerCard(event.giver,Math.min(3,event.giver.countCards('e')),'e',true).set('prompt','选择交给'+get.translation(event.gainner)+'的牌');
			    }
			    else event.goto(6);
			    'step 5'
			    if (result.links) event.cards.push(...result.links);
			    'step 6'
			    if(event.giver.countCards('j')){ //判定牌
					event.giver.choosePlayerCard(event.giver,Math.min(3,event.giver.countCards('j')),'j',true).set('prompt','选择交给'+get.translation(event.gainner)+'的牌');
		        }
		        else event.goto(8);
				'step 7'
				if (result.links) event.cards.push(...result.links);
				'step 8'
				if(event.cards.length) event.giver.give(event.cards,event.gainner);
				event.finish();
				'step 9'
				if(result.links) event.giver.give(result.links,event.gainner);
				},
				group:'shanhe_fenglve2',
				ai:{
					expose:0.25,
				},
			},
