                 if(name=='damageSource') return !game.nianshou_sizhan&&event.source&&((event.player!=player&&player.getEnemies().includes(event.player))||get.attitude(player,event.player)<0)&&((player.name1=='HH_nianshou'||player.name2=='HH_nianshou')?(((event.player!=player&&player.getEnemies().includes(event.player))||get.attitude(player,event.player)<0)):player.storage.nianshou_lingli_gainX&&player.storage.nianshou_lingli_gainX.includes(event.player));
                 if(name=='phaseEnd') return (game.nianshou_sizhan&&_status.currentPhase==player&&player.getHistory('sourceDamage').length==0)||player.hasSkill("nianshou_lingli_gain_die");
