			    	 if(trigger.source&&trigger.source==player) player.draw((((player.name1=='HH_nianshou'||player.name2=='HH_nianshou')&&((trigger.player!=player&&player.getEnemies().includes(trigger.player))||get.attitude(player,trigger.player)<0))||player.storage.nianshou_lingli_gainX.includes(trigger.player))?2:1);
