            NS_huihun:{
                audio:"ext:活动BOSS/audio/skill:true",
                enable:'phaseUse',
                usable:1,
                filter:function(event,player){
                if(!player.hasCard(card=>get.color(card,player)=='black'&&lib.filter.cardDiscardable(card, player),"h")) return false;
                return game.hasPlayer(function(current){return current.isDamaged()});
                },
                filterTarget:function(card,player,target){
                return target.isDamaged();
                },
                filterCard:function(card,player,target){
                if (!lib.filter.cardDiscardable(card, player)) return false;
                return get.color(card,player)=='black';
                },
                check:function(card){
                return 7-get.value(card);
                },
                content:function(){
                player.loseHp();
                target.recover(2,player);
                },
                ai:{
                    order:7,
                    result: {
                        player: function(player, target) {
                            if ((player.hp + player.countCards('h', 'tao') + player.countCards('h', 'jiu')) == 1) {
                                var canSave = game.hasPlayer(function(current) {return player.getFriends().includes(current) && current != player && (current.countCards('h', function(card) { return get.tag(card, 'save'); }) || current.hasSkillTag('save', true))});
                                if (!canSave) return -1;
                            }
                            var losehpCost = get.effect(player, {name: "losehp"}, player, player);
                            var recoverGain = get.recoverEffect(target, player, player);
                            if (player == target) recoverGain *= 2;
                            return losehpCost + recoverGain;
                        },
                        target: function(player, target) {
                            if ((player.hp + player.countCards('h', 'tao') + player.countCards('h', 'jiu')) == 1) {
                                var canSave = game.hasPlayer(function(current) {return player.getFriends().includes(current) && current != player && (current.countCards('h', function(card) { return get.tag(card, 'save'); }) || current.hasSkillTag('save', true))});
                                if (!canSave) return 0;
                            }
                            var basePriority = (target == player) ? 3 : 1;
                            var hpDiffPenalty = target.hp - player.hp;
                            var damagedHpBonus = target.getDamagedHp() + ((target == player) ? 1 : 0);
                            var finalScore = Math.min(Math.max(basePriority - hpDiffPenalty, 0), damagedHpBonus);
                            return Math.max(finalScore, 0.5);
                        }
                    }
                },
            },
