                                if(lib.linked.contains(get.nature(item))){
                                if(game.hasPlayer(function(current){return current!=player&&current.isLinked()&&player.canUse(item,current,null,true)&&get.effect(current,item,player,player)>0&&lib.card.sha.ai.canLink(player,current,item)})&&game.countPlayer(function(current){return current.isLinked()&&get.damageEffect(current,player,player,get.nature(item))>0})>1) return 3.1;
                                return 3;
                                }
