		    wenhe_lidaitaojiang:{
                audio:true,
                type:'trick',
                enable:true,
                selectTarget:1,
                filterTarget:function (card,player,target){
                    if(player==target) return false;
                    return target.countCards('h')+target.countCards('h')>1;
                },
                content:function (){
                    var cards=player.getCards('h').concat(target.getCards('h'));
                    var list1=[];
                    var list2=[];
                    var list=[list1,list2];
                    for(var i=0;i<cards.length;i++){
                        list.randomGet().push(cards[i]);
                    }
                    if(list1.length>0){
                        player.$draw(list1.length);
                        player.gain(list1);
                    }
                    if(list2.length>0){
                        target.$draw(list2.length);
                        target.gain(list2);
                    }
                },
                ai:{
                    basic:{
                        order:1,
                        useful:1,
                        value:5,
                    },
                    result:{
                        target:function (player,target){
                            var ph=player.countCards('h')-1;
                            var th=target.countCards('h');
                            return ph-th;
                        },
                    },
                },
                fullimage:true,
                fullskin:true,
            },
		    wenhe_douzhuanxingyi:{
                audio:true,
                type:'trick',
                enable:true,
                selectTarget:1,
                filterTarget:function (card,player,target){
                    return player!=target;
                },
                content:function (){
                    'step 0'
                    event.num=player.hp+target.hp-2;
                    event.num1=1;
                    event.num2=1;
                    'step 1'
                    var add=[1,2].randomGet();
                    if(event.num>0){
                        if(player.maxHp>event.num1&&target.maxHp>event.num2){
                            if(add!=1) event.num1++;
                            else event.num2++;
                            event.num--;
                        }
                        else if(player.maxHp==event.num1){
                            event.num2=event.num2+event.num;
                            event.num=0;
                        }
                        else if(target.maxHp==event.num2){
                            event.num1=event.num1+event.num;
                            event.num=0;
                        }
                    }
                    'step 2'
                    if(event.num>0) event.goto(1);
                    else{
                        var num;
                        if(player.hp>event.num1){
                            num=player.hp-event.num1;
                            player.loseHp(num);
                            target.recover(num);
                        }
                        else if(player.hp<event.num1){
                            num=event.num1-player.hp;
                            player.recover(num);
                            target.loseHp(num);
                        }
                    }
                },
                ai:{
                    basic:{
                        order:1,
                        useful:1,
                        value:5,
                    },
                    result:{
                        target:function (player,target){
                            var ph=player.hp;
                            var pm=player.maxHp;
                            var th=target.hp;
                            var tm=target.maxHp;
                            if(ph==pm&&th==tm) return 0;
                            if(th==tm) return ph-pm;
                            if(ph==pm) return tm-th;
                            if(ph==1) return ph-th;
                            if(th==1) return ph-th;
                            return ph-th;
                        },
                    },
                },
                fullimage:true,
                fullskin:true,
            },
