             "qihuan_cibi":{
                skills:['qihuan_cibi_skill'],
				fullimage:true,
                fullskin:true,
				type:'equip',
				subtype:'equip1',
				ai:{
                    equipValue:function(card,player){
                        var result=function(){
                            if(!player.countCards('h',function(card){return get.tag(card,'damage')&&get.color(card)=='black'})) return 1;
							if(player.getEquip('qihuan_cibi')&&player.countCards('h',function(card){return get.tag(card,'damage')&&get.color(card)=='black'&&game.hasPlayer(current=>{return get.attitude(player,current)<0&&get.distance(player,current)<=1&&get.damageEffect(current,player,player)>0&&lib.filter.targetEnabled2(card,player,current)})})&&_status.currentPhase==player) return 10;
				    		return 3;
						}();
						return result;
					},
                    basic:{
                        equipValue:3.5,
                        useful:2.5,
                        value:function(card,player,index,method){
                        if(player.isDisabled(get.subtype(card))) return 0.01;
                        var value=0;
                        var info=get.info(card);
                        var current=player.getEquip(info.subtype);
                        if(current&&card!=current){
                            value=get.value(current,player);
                        }
                        var equipValue=info.ai.equipValue;
                        if(equipValue==undefined){
                            equipValue=info.ai.basic.equipValue;
                        }
                        if(typeof equipValue=='function'){
                        if(method=='raw') return equipValue(card,player);
                        if(method=='raw2') return equipValue(card,player)-value;
                        return Math.max(0.1,equipValue(card,player)-value);
                        }
                        if(typeof equipValue!='number') equipValue=0;
                        if(method=='raw') return equipValue;
                        if(method=='raw2') return equipValue-value;
                        return Math.max(0.1,equipValue-value);
                        },
                    },
                    tag:{
						valueswap:1,
					},
                    result:{
                        target:function(player,target,card){
                             return get.equipResult(player,target,card.name);
                        },
                    },
                },
			},
